<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';zorunlu_rol('admin','yonetici','hakem');
$macId=(int)($_GET['mac_id']??$_POST['mac_id']??0);$kaynak=$_GET['kaynak']??'lig';if(!in_array($kaynak,['lig','turnuva'],true))$kaynak='lig';$ligTur=$_GET['lig_tur']??'takim';if(!in_array($ligTur,['takim','bireysel'],true))$ligTur='takim';$turnuvaTur=$_GET['turnuva_tur']??'takim';if(!in_array($turnuvaTur,['takim','bireysel'],true))$turnuvaTur='takim';$grupId=(int)($_GET['grup_id']??0);$durum=$_GET['durum']??'planlandi';if(!in_array($durum,['hepsi','planlandi','oynandi'],true))$durum='planlandi';
if($macId && $_SERVER['REQUEST_METHOD']==='GET'){$es=$pdo->prepare("SELECT set_no FROM mac_setleri WHERE mac_id=? AND ev_sahibi_set_puani=deplasman_set_puani AND kazanan IS NULL ORDER BY set_no LIMIT 1");$es->execute([$macId]);if($esitlikSet=$es->fetchColumn())redirect(BASE_URL.'/admin/esitlik-bozma.php?mac_id='.$macId.'&set='.$esitlikSet);}
if($macId && $_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['esitlik_bozma'])){if(!csrf_check($_POST['csrf']??'')){flash_set('hata','Güvenlik doğrulaması başarısız.');redirect(BASE_URL.'/admin/mac-skor.php');}$set=(int)$_POST['set_no'];$ev=max(0,min(210,(int)($_POST['ev_puan']??0)));$dep=max(0,min(210,(int)($_POST['dep_puan']??0)));$tur=(int)$pdo->prepare('SELECT COUNT(*) FROM esitlik_bozma_atislari WHERE kaynak=\'lig\' AND mac_id=? AND set_no=?')->execute([$macId,$set]);$say=$pdo->prepare("SELECT COUNT(*) FROM esitlik_bozma_atislari WHERE kaynak='lig' AND mac_id=? AND set_no=?");$say->execute([$macId,$set]);$tur=(int)$say->fetchColumn()+1;$pdo->prepare("INSERT INTO esitlik_bozma_atislari(kaynak,mac_id,set_no,tur_no,ev_puan,dep_puan) VALUES('lig',?,?,?,?,?)")->execute([$macId,$set,$tur,$ev,$dep]);if($ev!==$dep){$pdo->prepare('UPDATE mac_setleri SET kazanan=? WHERE mac_id=? AND set_no=?')->execute([$ev>$dep?'ev':'dep',$macId,$set]);flash_set('basari','Eşitlik bozuldu; sonraki sete geçildi.');redirect(BASE_URL.'/admin/mac-skor.php?mac_id='.$macId.'&set='.min(SET_SAYISI,$set+1));}flash_set('hata','Eşitlik devam ediyor. İki isimsiz sporcu yeniden 7 ok atmalıdır.');redirect(BASE_URL.'/admin/mac-skor.php?mac_id='.$macId.'&set='.$set);}
if($macId && $_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['csrf']??'')){flash_set('hata','Güvenlik doğrulaması başarısız.');redirect(BASE_URL.'/admin/mac-skor.php');}$set=max(1,min(SET_SAYISI,(int)($_POST['set_no']??1)));$m=$pdo->prepare('SELECT * FROM maclar WHERE id=?');$m->execute([$macId]);$m=$m->fetch();if(!$m){flash_set('hata','Maç bulunamadı.');redirect(BASE_URL.'/admin/mac-skor.php');}$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM sporcu_set_atislari WHERE mac_id=? AND set_no=?')->execute([$macId,$set]);$pdo->prepare('DELETE FROM mac_setleri WHERE mac_id=? AND set_no=?')->execute([$macId,$set]);$ins=$pdo->prepare('INSERT INTO sporcu_set_atislari(mac_id,set_no,sporcu_id,takim_id,ok1,ok2,ok3,ok4,ok5,ok6,ok7,set_toplam) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$top=['ev'=>0,'dep'=>0];foreach(['ev'=>$m['ev_sahibi_id'],'dep'=>$m['deplasman_id']] as $taraf=>$takim){$sporcular=$pdo->prepare('SELECT id FROM sporcular WHERE takim_id=? ORDER BY ad,soyad');$sporcular->execute([$takim]);foreach($sporcular->fetchAll() as $i=>$sp){$puan=max(0,min(210,(int)($_POST[$taraf][$sp['id']]??0)));$ins->execute([$macId,$set,$sp['id'],$takim,$puan,0,0,0,0,0,0,$puan]);$top[$taraf]+=$puan;}}$pdo->prepare('INSERT INTO mac_setleri(mac_id,set_no,ev_sahibi_set_puani,deplasman_set_puani,tamamlandi) VALUES(?,?,?,?,1)')->execute([$macId,$set,$top['ev'],$top['dep']]);$pdo->commit();if($set===SET_SAYISI){mac_istatistik_guncelle($pdo,$macId);flash_set('basari','Son set kaydedildi; maç sonucu oluşturuldu.');}else flash_set('basari',$set.'. set kaydedildi.');}catch(Throwable $e){$pdo->rollBack();flash_set('hata',$e->getMessage());}redirect(BASE_URL.'/admin/mac-skor.php?mac_id='.$macId.'&set='.min(SET_SAYISI,$set+1));}
$gruplarS=$pdo->prepare('SELECT g.id,g.grup_adi FROM gruplar g JOIN ligler l ON l.id=g.lig_id WHERE l.tur=? ORDER BY g.grup_adi');$gruplarS->execute([$ligTur]);$gruplar=$gruplarS->fetchAll();
$ligS=$pdo->prepare("SELECT m.*,t1.takim_adi ev,t2.takim_adi dep,g.grup_adi FROM maclar m JOIN takimlar t1 ON t1.id=m.ev_sahibi_id JOIN takimlar t2 ON t2.id=m.deplasman_id JOIN gruplar g ON g.id=m.grup_id JOIN ligler l ON l.id=g.lig_id WHERE l.tur=? AND (?=0 OR g.id=?) AND (?='hepsi' OR m.durum=?) ORDER BY m.tarih,m.hafta");$ligS->execute([$ligTur,$grupId,$grupId,$durum,$durum]);$ligMaclar=$ligS->fetchAll();
$bireyselFikstur=[];
if($kaynak==='lig'&&$ligTur==='bireysel'){$bf=$pdo->prepare("SELECT f.*,l.lig_adi,g.grup_adi,g.bolge_adi,g.kategori_adi,COUNT(DISTINCT k.id) sporcu_sayisi,COUNT(DISTINCT a.id) puan_sayisi FROM bireysel_fikstur f JOIN ligler l ON l.id=f.lig_id JOIN gruplar g ON g.id=f.grup_id LEFT JOIN bireysel_lig_kayitlari k ON k.lig_id=f.lig_id AND k.grup_id=f.grup_id LEFT JOIN bireysel_fikstur_atislari a ON a.fikstur_id=f.id WHERE (?=0 OR f.grup_id=?) GROUP BY f.id ORDER BY f.tarih,f.hafta_no");$bf->execute([$grupId,$grupId]);$bireyselFikstur=$bf->fetchAll();}
$ts=$pdo->prepare("SELECT tm.*,t.turnuva_adi,t.tur,CASE WHEN t.tur='takim' THEN a.takim_adi ELSE CONCAT(sa.ad,' ',sa.soyad) END ev,CASE WHEN t.tur='takim' THEN b.takim_adi ELSE CONCAT(sb.ad,' ',sb.soyad) END dep FROM turnuva_maclari tm JOIN turnuvalar t ON t.id=tm.turnuva_id LEFT JOIN takimlar a ON t.tur='takim' AND a.id=tm.katilimci1_id LEFT JOIN takimlar b ON t.tur='takim' AND b.id=tm.katilimci2_id LEFT JOIN sporcular sa ON t.tur='bireysel' AND sa.id=tm.katilimci1_id LEFT JOIN sporcular sb ON t.tur='bireysel' AND sb.id=tm.katilimci2_id WHERE t.tur=? AND (?='hepsi' OR tm.durum=?) ORDER BY t.turnuva_adi,tm.tur_no");$ts->execute([$turnuvaTur,$durum,$durum]);$turnuvaMaclar=$ts->fetchAll();
$mac=null;$ev=[];$dep=[];$mevcut=[];$set=max(1,min(SET_SAYISI,(int)($_GET['set']??1)));$sets=[];
if($macId){$s=$pdo->prepare('SELECT m.*,a.takim_adi ev,b.takim_adi dep FROM maclar m JOIN takimlar a ON a.id=m.ev_sahibi_id JOIN takimlar b ON b.id=m.deplasman_id WHERE m.id=?');$s->execute([$macId]);$mac=$s->fetch();if($mac){foreach(['ev'=>'ev_sahibi_id','dep'=>'deplasman_id'] as $taraf=>$alan){$s=$pdo->prepare('SELECT id,ad,soyad FROM sporcular WHERE takim_id=? ORDER BY ad,soyad');$s->execute([$mac[$alan]]);$$taraf=$s->fetchAll();}$s=$pdo->prepare('SELECT * FROM sporcu_set_atislari WHERE mac_id=? AND set_no=?');$s->execute([$macId,$set]);foreach($s->fetchAll() as $x)$mevcut[$x['takim_id']][$x['sporcu_id']]=$x['set_toplam'];$s=$pdo->prepare('SELECT * FROM mac_setleri WHERE mac_id=? ORDER BY set_no');$s->execute([$macId]);$sets=$s->fetchAll();}}
ob_start();?>
<?php if(!$mac): ?><div class="card"><div class="card-head"><h2>Skor Girişi — Karşılaşma / Atış Seç</h2></div><form method="get" class="skor-filtre"><label>Kaynak<select name="kaynak" onchange="this.form.submit()"><option value="lig" <?= $kaynak==='lig'?'selected':'' ?>>Lig Karşılaşmaları</option><option value="turnuva" <?= $kaynak==='turnuva'?'selected':'' ?>>Turnuvalar</option></select></label><?php if($kaynak==='lig'): ?><label>Lig türü<select name="lig_tur" onchange="this.form.submit()"><option value="takim" <?= $ligTur==='takim'?'selected':'' ?>>Takım Ligi</option><option value="bireysel" <?= $ligTur==='bireysel'?'selected':'' ?>>Bireysel Bölge Ligleri</option></select></label><label>Grup<select name="grup_id"><option value="0">Tüm gruplar</option><?php foreach($gruplar as $g): ?><option value="<?= $g['id'] ?>" <?= $grupId==(int)$g['id']?'selected':'' ?>><?= e($g['grup_adi']) ?></option><?php endforeach; ?></select></label><?php else: ?><label>Turnuva türü<select name="turnuva_tur" onchange="this.form.submit()"><option value="takim" <?= $turnuvaTur==='takim'?'selected':'' ?>>Takım Turnuvası</option><option value="bireysel" <?= $turnuvaTur==='bireysel'?'selected':'' ?>>Bireysel Turnuva</option></select></label><?php endif; ?><label>Durum<select name="durum"><option value="hepsi">Tümü</option><option value="planlandi" <?= $durum==='planlandi'?'selected':'' ?>>Planlanan</option><option value="oynandi" <?= $durum==='oynandi'?'selected':'' ?>>Tamamlanan</option></select></label><button class="btn btn-primary">Listele</button></form><?php if($kaynak==='lig'&&$ligTur==='bireysel'): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Lig / Grup</th><th>Kategori</th><th>Hafta</th><th>Atış Tarihi</th><th>Atış Alanı</th><th>Sporcu</th><th></th></tr></thead><tbody><?php foreach($bireyselFikstur as $x): ?><tr><td><?= e($x['lig_adi'].' / '.($x['bolge_adi']?:$x['grup_adi'])) ?></td><td><?= e($x['kategori_adi']) ?></td><td><?= !empty($x['hafta_no'])?(int)$x['hafta_no'].'. Hafta':e($x['aciklama']) ?></td><td><?= tr_tarih($x['tarih']) ?></td><td><?= e($x['yer']) ?></td><td><?= (int)$x['sporcu_sayisi'] ?></td><td><a class="btn btn-sm btn-primary" href="<?= BASE_URL ?>/admin/bireysel-skor.php?fikstur_id=<?= (int)$x['id'] ?>">Puan Gir</a></td></tr><?php endforeach; ?><?php if(!$bireyselFikstur): ?><tr><td colspan="7" class="muted">Bu gruplar için henüz atış fikstürü oluşturulmamış.</td></tr><?php endif; ?></tbody></table></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Organizasyon</th><th>Ev</th><th>Skor</th><th>Deplasman</th><th></th></tr></thead><tbody><?php foreach($kaynak==='lig'?$ligMaclar:$turnuvaMaclar as $x): ?><tr><td><?= e($kaynak==='lig'?$x['grup_adi']:$x['turnuva_adi']) ?></td><td><?= e($x['ev']) ?></td><td><?= $kaynak==='lig'?(int)$x['ev_sahibi_set'].' - '.(int)$x['deplasman_set']:(int)$x['puan1'].' - '.(int)$x['puan2'] ?></td><td><?= e($x['dep']) ?></td><td><a class="btn btn-sm btn-primary" href="<?= $kaynak==='lig'?'?mac_id='.(int)$x['id']:BASE_URL.'/admin/turnuva-skor.php?id='.(int)$x['id'] ?>">Skor Gir</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php else: ?><form method="post" class="form"><div class="card"><div class="card-head"><h2><?= e($mac['ev']) ?> <span class="muted">vs</span> <?= e($mac['dep']) ?></h2><span class="badge"><?= $set ?>. Set / <?= SET_SAYISI ?></span></div><p class="muted">Her sporcu için 7 okun toplam puanını tek alana yazın. Bu set kaydedildiğinde sonraki sete geçilir.</p><?= csrf_field() ?><input type="hidden" name="mac_id" value="<?= $macId ?>"><input type="hidden" name="set_no" value="<?= $set ?>"><div class="grid-2"><?php foreach(['ev'=>[$ev,$mac['ev_sahibi_id'],$mac['ev']],'dep'=>[$dep,$mac['deplasman_id'],$mac['dep']]] as $taraf=>$v): ?><section class="card"><h3><?= e($v[2]) ?></h3><?php foreach($v[0] as $sp): ?><label class="grid-2"><span><?= e($sp['ad'].' '.$sp['soyad']) ?></span><input type="number" name="<?= $taraf ?>[<?= $sp['id'] ?>]" min="0" max="210" value="<?= (int)($mevcut[$v[1]][$sp['id']]??0) ?>" placeholder="7 ok toplamı"></label><?php endforeach; ?></section><?php endforeach; ?></div><button class="btn btn-primary"><?= $set<SET_SAYISI?'Seti Kaydet ve Sonraki Sete Geç':'Son Seti Kaydet ve Maçı Tamamla' ?></button></div></form><section class="card"><h2>Tamamlanan Setler</h2><?php foreach($sets as $x): ?><p><?= $x['set_no'] ?>. Set: <?= $x['ev_sahibi_set_puani'] ?> - <?= $x['deplasman_set_puani'] ?></p><?php endforeach; ?></section><?php endif; ?><?php $admin_baslik='Skor Girişi';$admin_aktif='skor';$admin_icerik=ob_get_clean();require __DIR__.'/partials/layout.php';?>
